diff --git a/xdsl/dialects/eqsat.py b/xdsl/dialects/eqsat.py
index 3985b83ac8..baec5f2dcb 100644
--- a/xdsl/dialects/eqsat.py
+++ b/xdsl/dialects/eqsat.py
@@ -13,12 +13,14 @@

 from typing import ClassVar

+from xdsl.dialects.builtin import IntAttr
 from xdsl.ir import Attribute, Dialect, SSAValue
 from xdsl.irdl import (
     AnyAttr,
     IRDLOperation,
     VarConstraint,
     irdl_op_definition,
+    opt_attr_def,
     result_def,
     var_operand_def,
 )
@@ -32,16 +34,26 @@ class EClassOp(IRDLOperation):
     name = "eqsat.eclass"
     arguments = var_operand_def(T)
     result = result_def(T)
+    min_cost_index = opt_attr_def(IntAttr)

     assembly_format = "$arguments attr-dict `:` type($result)"

-    def __init__(self, *arguments: SSAValue, res_type: Attribute | None = None):
+    def __init__(
+        self,
+        *arguments: SSAValue,
+        min_cost_index: IntAttr | None = None,
+        res_type: Attribute | None = None,
+    ):
         if not arguments:
             raise DiagnosticException("eclass op must have at least one operand")
         if res_type is None:
             res_type = arguments[0].type

-        super().__init__(operands=[arguments], result_types=[res_type])
+        super().__init__(
+            operands=[arguments],
+            result_types=[res_type],
+            attributes={"min_cost_index": min_cost_index},
+        )

     def verify_(self) -> None:
         # Check that none of the operands are produced by another eclass op.
diff --git a/xdsl/transforms/eqsat_add_costs.py b/xdsl/transforms/eqsat_add_costs.py
index 91760e3440..4c05be7643 100644
--- a/xdsl/transforms/eqsat_add_costs.py
+++ b/xdsl/transforms/eqsat_add_costs.py
@@ -11,6 +11,9 @@
 def get_eqsat_cost(value: SSAValue) -> int | None:
     if not isinstance(value, OpResult):
         return 0
+    if isinstance(value.op, eqsat.EClassOp):
+        if (min_cost_index := value.op.min_cost_index) is not None:
+            return get_eqsat_cost(value.op.operands[min_cost_index.data])
     cost_attribute = value.op.attributes.get(EQSAT_COST_LABEL)
     if cost_attribute is None:
         return None
@@ -41,10 +44,12 @@ def add_eqsat_costs(block: Block):

         if isinstance(op, eqsat.EClassOp):
             cost = min(cost for cost in costs if cost is not None)
+            index = costs.index(cost)
+            op.min_cost_index = IntAttr(index)
         else:
             # For now, set the cost to the costs of the operands + 1
             cost = sum(cost for cost in costs if cost is not None) + 1
-        op.attributes[EQSAT_COST_LABEL] = IntAttr(cost)
+            op.attributes[EQSAT_COST_LABEL] = IntAttr(cost)


 class EqsatAddCostsPass(ModulePass):

